import { z } from 'zod';
import type { Config } from '../config.js';
import { HttpError } from '../http.js';
import { initialQuestion, link, putNote, questionSchema, type ProjectDocument } from './model.js';
import { reportAIFailure, runClaude } from './claude.js';
import { ensureValidation } from './validation.js';
import { caseForModel, findExperiences, projectQuery } from './experiences.js';

// The agenda is deterministic; every question and hypothesis is generated by the
// model from the actual conversation. There is no fallback. Research instruments
// are generated afterwards in the background, so the chat closes immediately.
export const branches = [
  { id: 'segment', goal: 'Quién vive la necesidad y en qué contexto, sin exigir un segmento perfecto.' },
  { id: 'situation', goal: 'Un ejemplo simple que ayude a entender cuándo aparece la necesidad.' },
  { id: 'pain', goal: 'La principal dificultad o fricción; si el caso salió bien, no fabriques un dolor ni audites más casos.' },
] as const;
type Branch = typeof branches[number]['id'];
export const MAX_ANSWERS = 4; // Chat grill: initial idea + at most three clarifying answers.
// By voice only substantive answers are saved (filler and questions are not). Three questions in
// all: the initial one (the idea) and at most two more.
export const MAX_REALTIME_ANSWERS = 3;
export const maxAnswers = (doc: ProjectDocument) => doc.intake.engine === 'realtime' ? MAX_REALTIME_ANSWERS : MAX_ANSWERS;

