/** The grill's output; GPT-Realtime's frame_problem tool and the Claude fallback share it. */
export function intakeSchema(mustComplete: boolean) {
  // Every field is always sent, but the frame is only checked when the answer is
  // about a business: an off-topic turn may leave it empty and carries the redirect.
  return z.object({ onTopic: z.boolean(), redirect: z.string().max(400).default(''), name: z.string().max(60), problem: z.string().max(1200),
    segment: z.string().max(600), currentProcess: z.string().max(800), painPoints: z.string().max(800),
    hypotheses: z.array(z.object({ title: z.string().max(180), body: z.string().max(450) })).max(3),
    complete: z.boolean(), branch: z.enum(branches.map(b => b.id) as [Branch, ...Branch[]]).nullable(),
    nextQuestion: questionSchema.omit({ id: true, options: true }).nullable(),
  }).superRefine((result, ctx) => {
    if (!result.onTopic) { if (!result.redirect.trim()) ctx.addIssue({ code: 'custom', path: ['redirect'], message: 'Con onTopic=false, redirect explica brevemente y retoma la pregunta.' }); return; }
    if (!result.name.trim()) ctx.addIssue({ code: 'custom', path: ['name'], message: 'Falta el nombre corto del proyecto.' });
    if (!result.problem.trim()) ctx.addIssue({ code: 'custom', path: ['problem'], message: 'Falta la síntesis del problema.' });
    if (result.hypotheses.length !== 3 || result.hypotheses.some(h => !h.title.trim() || !h.body.trim())) ctx.addIssue({ code: 'custom', path: ['hypotheses'], message: 'Hacen falta exactamente tres hipótesis con title y body.' });
    if (mustComplete && !result.complete) ctx.addIssue({ code: 'custom', path: ['complete'], message: 'No quedan preguntas: complete=true y nextQuestion=null.' });
    if (!result.complete && (!result.branch || !result.nextQuestion?.prompt.trim())) ctx.addIssue({ code: 'custom', path: ['nextQuestion'], message: 'Si complete=false incluí una pregunta abierta y su branch; si ya alcanza, complete=true y nextQuestion=null.' });
  });
}
export type IntakeOutput = z.infer<ReturnType<typeof intakeSchema>>;

/** What the grill knows at this turn: the conversation, the current synthesis and research notes. */
export function intakeContext(doc: ProjectDocument) {
  const body = (id: string) => doc.answers.length > 1 ? doc.nodes.find(n => n.id === id)?.body ?? '' : '';
  const limit = maxAnswers(doc), mustComplete = doc.answers.length >= limit, deep = doc.intake.engine === 'realtime';
  return { conversation: doc.answers.map(a => ({ question: a.prompt, answer: a.value })),
    current: { problem: body('problem'), segment: body('segment'), currentProcess: body('alternative'), painPoints: body('impact') },
    research: { status: doc.research.status, notes: doc.nodes.filter(n => !n.archived && (n.kind === 'source' || n.discovery)).map(n => ({ title: n.title, body: n.body })) },
    remainingQuestions: Math.max(0, limit - doc.answers.length), dimensions: branches,
    instruction: mustComplete ? 'No hagas más preguntas. Cerrá ahora con un encuadre provisional y tres hipótesis específicas; lo incierto se investiga.'
      : deep ? 'Aportá algo concreto y hacé UNA pregunta sobre el vacío más importante, o cerrá si ya hay un problema planteable. Si el fundador no sabe, proponé un supuesto y avanzá.'
      : 'Hacé como máximo una pregunta útil o cerrá si ya alcanza para investigar.' };
}

/** The grill context plus the documented cases that resemble this project. */
export async function grillContext(config: Config, doc: ProjectDocument) {
  const cases = await findExperiences(config, projectQuery(doc), 4);
  return { ...intakeContext(doc), documentedCases: cases.map(caseForModel) };
}

/**
 * An answer that is not about a business idea does not advance the grill: the
 * answer is dropped and the cofounder's redirect waits in the chat. Returns
 * true when nothing is left (the idea itself was off topic) and the project
 * should be discarded.
 */
export function rejectIntakeTurn(doc: ProjectDocument, redirect: string) {
  const dropped = doc.answers.pop();
  if (!doc.answers.length || !dropped) return true;
  doc.question = { id: dropped.questionId, prompt: dropped.prompt, options: [], placeholder: dropped.placeholder ?? '' };
  doc.intake = { ...doc.intake, status: 'idle', message: redirect.trim() };
  return false;
}

/** Writes a grill turn into the map: the synthesis notes, then the next question or the hypotheses. */
export function applyIntake(doc: ProjectDocument, output: IntakeOutput) {
  putNote(doc, { id: 'problem', kind: 'problem', title: 'Problema', body: output.problem }, { x: 0, y: 0 });
  const definitions = [
    ['segment', 'Personas afectadas', output.segment, { x: -350, y: -220 }, 'affects'],
    ['alternative', 'Proceso actual', output.currentProcess, { x: 300, y: -230 }, 'uses'],
    ['impact', 'Pain points', output.painPoints, { x: 330, y: 70 }, 'causes'],
  ] as const;
  for (const [kind, title, body, position, relation] of definitions) {
    if (!body.trim()) continue;
    putNote(doc, { id: kind, kind, title, body }, position); link(doc, 'problem', kind, relation);
  }
  const branch = output.branch, question = output.nextQuestion;
  if (!output.complete && branch && question) {
    doc.question = { ...question, id: `${branch}-${doc.answers.length}`, options: [] };
  } else {
    output.hypotheses.forEach((hypothesis, i) => {
      const id = `hypothesis-${i}`;
      putNote(doc, { id, kind: 'hypothesis', ...hypothesis }, { x: -340 + i * 310, y: 530 }); link(doc, 'problem', id, 'assumes');
    });
    ensureValidation(doc);
    doc.question = null;
  }
}

export async function advanceIntake(config: Config, doc: ProjectDocument): Promise<{ name: string; onTopic: boolean; discard: boolean }> {
  if (!config.ai) throw new HttpError(503, 'Iniciá sesión en Claude Code para generar la entrevista con IA.');
  try {
    const { output } = await runClaude(config, { schema: intakeSchema(doc.answers.length >= maxAnswers(doc)), system: grillPrompt, prompt: JSON.stringify(await grillContext(config, doc)) });
    if (!output.onTopic) return { name: '', onTopic: false, discard: rejectIntakeTurn(doc, output.redirect) };
    applyIntake(doc, output);
    return { name: output.name, onTopic: true, discard: false };
  } catch (error) {
    throw new HttpError(502, `${reportAIFailure(config, 'intake', error).message} Se agotaron los reintentos; podés volver a enviar tu respuesta.`);
  }
}

export function rewindIntake(doc: ProjectDocument, index: number) {
  doc.intake = { status: 'idle', id: null, questionId: null, message: '', startedAt: null };
  if (index === 0) { Object.assign(doc, { question: initialQuestion, answers: [], nodes: [], edges: [], positions: {}, validation: [] }); return }
  const answer = doc.answers[index];
  doc.question = { id: answer.questionId, prompt: answer.prompt, options: [], placeholder: answer.placeholder ?? '' };
  doc.answers = doc.answers.slice(0, index); doc.validation = [];
  const hypotheses = new Set(doc.nodes.filter(n => n.kind === 'hypothesis').map(n => n.id));
  doc.nodes = doc.nodes.filter(n => !hypotheses.has(n.id));
  doc.edges = doc.edges.filter(e => !hypotheses.has(e.source) && !hypotheses.has(e.target));
  for (const id of hypotheses) delete doc.positions[id];
}

// The three notes around the problem; research rewrites them with sources.
export const mainNotes = [
  ['segment', 'Personas afectadas', { x: -350, y: -220 }, 'affects'],
  ['alternative', 'Proceso actual', { x: 300, y: -230 }, 'uses'],
  ['impact', 'Pain points', { x: 330, y: 70 }, 'causes'],
] as const;
